def extra_cable(n: int, edges: list[list[int]]) -> list[int]:
    parent = list(range(n + 1))          # nodes are 1..n
    size = [1] * (n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving: iterative compression
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return [a, b]                # already connected: this cable closes the loop
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra                  # smaller tree under the larger root
        size[ra] += size[rb]
    return []
